Lemma rw_forget : forall m A cs, rw_cells asegs m A cs -> rw_cells asegs m A [CB (cells_size cs) (cells_bytes cs)].
Proof.
ltac2:(KReplay.run1 (kr_t_I_pcseg ()) [] "h01Ah11Hh22csh31lh41mp;1p;4p;3p;2p;6p;7g0000R0p4p710g000NR1p4p710R2p8p1000lp4p7210P2p8g001Xj10Tg002=j14Tg002[j13Tg003>j15Tg003`j1:Tg004@j42Tg0059j19Tg005Yj31TP0j26TP1j67Tg0066j78Tg0074#0#0#0R1#0#0#0#4#3%41#3#5[g007Yg0087R1#:R0g008oR2f2R3f1R4f0R5C2P2f3R6P3%91R3P4P3P0P4P2f4P6A1135C2X30P5A11431614E7F8W1W2W0W4o"). Qed.

(* [comment removed for export] *)
Definition DIR0 : list cell := [CB 8 (repeat z8 8); C8 (Z_to_bv 64 (-1)); CB 24 (repeat z8 24)].

(* [comment removed for export] *)
Definition pcl_st (pc : Z) (ra gp tp t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s6 t3 t4 t5 t6 : word) (q p ap : Z)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state :=
  MS (mkR ra (Z_to_bv 64 (q + -2240)) gp tp t0 t1 t2 (Z_to_bv 64 q) s1 a0 a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 10) (Z_to_bv 64 p)
          (Z_to_bv 64 90486) (Z_to_bv 64 ap) s6 (Z_to_bv 64 9) (Z_to_bv 64 (q + -2184)) (Z_to_bv 64 12297829382473034410)
          (Z_to_bv 64 (-1)) (Z_to_bv 64 37) t3 t4 t5 t6)
     F (Z_to_bv 64 pc) fc None m (seg_rom asegs).

(* [comment removed for export] *)
Definition pcs_post (q : Z) (sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x598c8) fc None m' (seg_rom asegs)
    /\ munch [(q + -2216, q + -2176)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' (q + -2216) DIR0.

Lemma pcom_setup_spec : forall (q : Z) (junk : list byte)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m : mem),
  s0 = Z_to_bv 64 q -> s8 = Z_to_bv 64 (q + -2184) -> s9 = Z_to_bv 64 12297829382473034410 -> s10 = Z_to_bv 64 (-1) ->
  rw_cells asegs m (q + -2216) [CB 40 junk] -> q mod 16 = 0 -> 2240 <= q < 2^63 -> mem_inv asegs m ->
  evt asegs (pcs_post q sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
